    "created_at": "2019-01-01T00:00:00",
    "shares": [
     {
      "debtor": {
       "name": "string",
       "email": "user@example.com"
      },
      "debt_amount": 0.0
     }
    ],
    "creator": {
     "name": "string",
     "email": "user@example.com"
    },
    "payer": {
     "name": "string",
     "email": "user@example.com"
    },
    "paid_amount": 0.0
   }
  ],
  "failure": {
   "message": "string"
  }
 }
